import {installPairCode} from './pair-code.js';
const $=id=>document.getElementById(id),params=new URLSearchParams(location.hash.slice(1));let token=params.get('token')||sessionStorage.getItem('utilsim-runner-token');if(params.has('token')){sessionStorage.setItem('utilsim-runner-token',token);history.replaceState(null,'',location.pathname);}
const code=installPairCode($('pair-code'));let state;
async function request(path,data){const r=await fetch('/local/'+path,{method:data===undefined?'GET':'POST',headers:{Authorization:'Bearer '+token,'Content-Type':'application/json'},body:data===undefined?undefined:JSON.stringify(data)});if(!r.ok){let message;try{message=(await r.json()).detail;}catch{}throw Error(message||'The local runner could not answer.');}return r;}
function download(blob,name){const a=document.createElement('a'),url=URL.createObjectURL(blob);a.href=url;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);}
async function refresh(){try{state=await(await request('status')).json();$('runner-status').textContent=state.status;$('storage').textContent='Storage: '+state.storage;$('pair').hidden=state.paired;$('active-name').textContent=state.active?state.active.name+' · revision '+state.active.revision:'Ready for a job';const p=state.progress;$('phase').textContent=!state.active?'All completed results are saved on this drive.':p.stage?`${p.stage} · ${p.stageSeconds??0}s`:'Waiting for the next stage';$('progress').max=p.total||1;$('progress').value=p.completed||0;$('eta').textContent=!state.active?'Ready for the next revision.':p.etaSeconds==null?'ETA will appear after the first district finishes.':`${p.completed}/${p.total} districts · about ${Math.ceil(p.etaSeconds/60)} min remaining`;$('pause').textContent=state.paused?'Resume processing':'Pause after current district';$('runner-error').textContent=state.error||'';$('results').replaceChildren(...state.results.map(name=>{const button=document.createElement('button');button.className='text-button';button.textContent='Download summary · '+name.slice(0,12);button.onclick=async()=>{try{download(await(await request('results/'+name.split('.')[0])).blob(),name);}catch(e){$('runner-error').textContent=e.message;}};return button;}));}catch(e){$('runner-error').textContent=e.message;}}
$('pair-form').onsubmit=async e=>{e.preventDefault();try{await request('pair',{portal:$('portal-origin').value,code:code()});await refresh();}catch(e){$('runner-error').textContent=e.message;}};
$('pause').onclick=async()=>{try{await request('pause',{paused:!state.paused});await refresh();}catch(e){$('runner-error').textContent=e.message;}};
$('job-file').onchange=async e=>{try{const f=e.target.files[0];if(f.size>2000000)throw Error('Choose a small job JSON file, not a full archive.');await request('import',JSON.parse(await f.text()));await refresh();}catch(e){$('runner-error').textContent=e.message;}};
await refresh();setInterval(refresh,3000);
